interface DebounceOptions {
  leading?: boolean;
  trailing?: boolean;
}

interface DebouncedFunction<T extends (...args: any[]) => any> {
  (...args: Parameters<T>): void;
  cancel: () => void;
  flush: () => void;
  pending: () => boolean;
}

function debounce<T extends (...args: any[]) => any>(
  fn: T,
  wait: number,
  options: DebounceOptions = {}
): DebouncedFunction<T> {
  const { leading = false, trailing = true } = options;

  let timeoutId: ReturnType<typeof setTimeout> | null = null;
  let lastArgs: Parameters<T> | null = null;
  let lastThis: any = null;
  let result: ReturnType<T> | undefined;
  let lastCallTime = 0;

  function invokeFunc() {
    const args = lastArgs!;
    const thisArg = lastThis;
    lastArgs = null;
    lastThis = null;
    result = fn.apply(thisArg, args);
    return result;
  }

  function startTimer(timerExpired: () => void) {
    timeoutId = setTimeout(timerExpired, wait);
  }

  function shouldInvoke(time: number): boolean {
    return timeoutId === null || time - lastCallTime >= wait;
  }

  function trailingEdge() {
    timeoutId = null;
    if (trailing && lastArgs) {
      return invokeFunc();
    }
    lastArgs = null;
    lastThis = null;
    return result;
  }

  function leadingEdge(time: number) {
    lastCallTime = time;
    startTimer(timerExpired);
    return leading ? invokeFunc() : result;
  }

  function timerExpired() {
    const time = Date.now();
    if (shouldInvoke(time)) {
      return trailingEdge();
    }
    startTimer(timerExpired);
  }

  function remainingWait(time: number) {
    return wait - (time - lastCallTime);
  }

  function debounced(this: any, ...args: Parameters<T>): void {
    const time = Date.now();
    const isInvoking = shouldInvoke(time);

    lastArgs = args;
    lastThis = this;
    lastCallTime = time;

    if (isInvoking) {
      if (timeoutId === null) {
        leadingEdge(time);
      } else {
        // Cleared timer between calls — restart trailing window
        startTimer(timerExpired);
      }
    } else if (timeoutId === null) {
      startTimer(timerExpired);
    }
  }

  debounced.cancel = () => {
    if (timeoutId !== null) clearTimeout(timeoutId);
    timeoutId = null;
    lastArgs = null;
    lastThis = null;
    lastCallTime = 0;
  };

  debounced.flush = () => {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
      return trailingEdge();
    }
    return result;
  };

  debounced.pending = () => timeoutId !== null;

  return debounced;
}
```

## How It Works

The debouncer maintains a few pieces of state:

- **`timeoutId`** — the active trailing timer (or `null` if idle)
- **`lastArgs` / `lastThis`** — the most recent call's arguments and `this` context, so the trailing invocation can fire with up-to-date data
- **`lastCallTime`** — timestamp of the most recent call, used to decide whether a new "burst" has started

Flow when `debounced(...)` is called:

1. **Record the call** — store args/`this`, update `lastCallTime`.
2. **`shouldInvoke`** — true if no timer is running, or if `wait` ms have elapsed since the previous call (meaning a new burst has begun).
3. **Leading edge** — if it's a new burst and `leading: true`, invoke immediately, then start the trailing timer.
4. **Subsequent calls within the window** — do *not* invoke (leading already handled); `lastArgs` keeps being overwritten. The trailing timer is restarted each time, so the function fires once `wait` ms pass after the *last* call.
5. **Trailing edge** — when the timer expires and `trailing: true`, invoke once with the latest args.

The `cancel()`, `flush()`, and `pending()` helpers give callers control to abort, force execution, or query state — very useful for cleanup or navigation events.

