class EventEmitter {
  constructor() {
    this.events = new Map();
  }

  on(event, listener) {
    if (typeof listener !== "function") {
      throw new TypeError("Listener must be a function");
    }

    const listeners = this.events.get(event) ?? [];
    listeners.push(listener);
    this.events.set(event, listeners);

    // Return an unsubscribe function for convenience.
    return () => this.off(event, listener);
  }

  off(event, listener) {
    const listeners = this.events.get(event);
    if (!listeners) return;

    const remaining = listeners.filter(fn => fn !== listener);

    if (remaining.length > 0) {
      this.events.set(event, remaining);
    } else {
      this.events.delete(event);
    }
  }

  once(event, listener) {
    const wrapper = (...args) => {
      // Remove before calling, so re-entrant emits won't call it again.
      this.off(event, wrapper);
      listener(...args);
    };

    // Keep a reference to the wrapper so callers can remove the listener
    // by passing the original function to off().
    wrapper.originalListener = listener;
    this.on(event, wrapper);
  }

  emit(event, ...args) {
    const listeners = this.events.get(event);
    if (!listeners) return false;

    // Copy the list so changes made during emission don't affect this pass.
    for (const listener of [...listeners]) {
      listener(...args);
    }

    return true;
  }
